'use client';

import * as React from 'react';
import {createComponent, type EventName} from '@lit/react';
import '@material/web/labs/gb/components/pulltorefresh/md-gb-pull-to-refresh.js';
import {PullToRefreshElement} from '@material/web/labs/gb/components/pulltorefresh/pull-to-refresh-element.js';

/**
 * A Material Design component. Wraps <md-gb-pull-to-refresh>.
 * Docs: https://material-web.dev/3.0/components/pull-to-refresh/
 */
export const MdPullToRefresh = createComponent({
  react: React,
  tagName: 'md-gb-pull-to-refresh',
  elementClass: PullToRefreshElement,
  events: {
    onRefresh: 'refresh' as EventName<Event>,
  },
});

export type MdPullToRefreshProps = React.ComponentProps<typeof MdPullToRefresh>;
